// Returns a wrapper object for the known response body format(s).
//
// Corresponds with GET /clusters (the `ClusterList` operationId).
func (c *ClientWithResponses) ClusterListWithResponse(ctx context.Context, reqEditors ...RequestEditorFn) (*ClusterListResponse, error) {
	rsp, err := c.ClusterList(ctx, reqEditors...)
	if err != nil {
		return nil, err
	}
	return ParseClusterListResponse(rsp)
}

// ClusterCreateWithBodyWithResponse Create a dedicated cluster.
//
// Starts creation of a dedicated cluster for an organization. Provisioning begins once payment is settled, and the response tells you what is needed to get there — exactly one of three shapes:
